#!/usr/bin/env python3
"""Create a new union adapter; never overwrite the original or edit patient data."""
from pathlib import Path
import argparse
import hashlib

PATCH_BLOCK = '# v1.1: explicit assembly declaration, key reconciliation, and audited historical repair.\nif (!identical(a$current_build, "GRCh38") || !identical(a$legacy_build, "GRCh38")) {\n  stop("This adapter supports explicitly declared GRCh38 inputs only; no liftover is performed")\n}\nif (!file.exists(a$legacy_a10)) stop("Missing historical A10: ", a$legacy_a10)\ninput_paths <- c(input_paths, legacy_a10 = a$legacy_a10)\ninput_hashes <- c(input_hashes, legacy_a10 = sha(a$legacy_a10))\nlegacy_a10 <- read_tab(a$legacy_a10)\nneed(legacy_a10, c("gene_symbol", "best_candidate_id"), "Historical A10")\ncanonical_id <- function(values) {\n  vapply(as.character(values), function(z) {\n    if (blank(z)) return(NA_character_)\n    z <- trimws(z)\n    if (grepl("^(GRCh[0-9]+|hg[0-9]+):", z, ignore.case = TRUE)) {\n      prefix <- sub(":.*$", "", z)\n      if (toupper(prefix) != "GRCH38") stop("Unexpected assembly prefix: ", prefix)\n      z <- sub("^[^:]+:", "", z)\n    }\n    fields <- strsplit(z, ":", fixed = TRUE)[[1]]\n    if (length(fields) != 4L || any(!nzchar(fields)) ||\n        !grepl("^[1-9][0-9]*$", fields[2])) stop("Unsupported coordinate-style candidate ID: ", z)\n    fields[1] <- sub("^chr", "", fields[1], ignore.case = TRUE)\n    if (fields[1] %in% c("x", "y", "mt", "m")) fields[1] <- toupper(fields[1])\n    if (fields[1] == "M") fields[1] <- "MT"\n    fields[3:4] <- toupper(fields[3:4])\n    paste(fields, collapse = ":")\n  }, character(1), USE.NAMES = FALSE)\n}\nset(x, j = "best_candidate_id_original", value = x$best_candidate_id)\nset(a2, j = "candidate_id_original", value = a2$candidate_id)\nset(f, j = "candidate_id_original", value = f$candidate_id)\nset(s, j = "candidate_id_original", value = as.character(s$candidate_id))\nset(x, j = "best_candidate_id", value = canonical_id(x$best_candidate_id))\nset(a2, j = "candidate_id", value = canonical_id(a2$candidate_id))\nset(f, j = "candidate_id", value = canonical_id(f$candidate_id))\nset(s, j = "candidate_id", value = canonical_id(s$candidate_id))\nfor (ids in list(x$best_candidate_id, a2$candidate_id, f$candidate_id, s$candidate_id)) {\n  if (anyNA(ids) || anyDuplicated(ids)) stop("Missing or colliding current IDs after format reconciliation")\n}\nold[, historical_source_row := .I]\nset(old, j = "original_gene", value = old$gene)\nset(old, j = "original_variant", value = old$variant)\nset(old, j = "variant", value = canonical_id(old$variant))\nset(old, j = "gene", value = trimws(old$gene))\nold[, key_repair_status := fifelse(blank(gene), "unresolved_missing_gene", "original_gene_present")]\nlookup <- unique(data.table(\n  variant = canonical_id(legacy_a10$best_candidate_id),\n  recovered_gene = trimws(legacy_a10$gene_symbol)\n))\nlookup <- lookup[!is.na(variant) & !blank(recovered_gene)]\nlookup <- lookup[, .(n_gene_mappings = uniqueN(recovered_gene), recovered_gene = recovered_gene[1L]), by = variant]\nli <- match(old$variant, lookup$variant)\nrepair <- which(blank(old$gene) & !is.na(li) & lookup$n_gene_mappings[li] == 1L)\nif (length(repair)) {\n  set(old, i = repair, j = "gene", value = lookup$recovered_gene[li[repair]])\n  set(old, i = repair, j = "key_repair_status", value = "gene_recovered_from_unique_historical_A10_allele_match")\n}\nold_all <- copy(old)\nold_unresolved <- copy(old[blank(gene) | is.na(variant)])\nif (nrow(old_unresolved)) {\n  old_unresolved[, unresolved_reason := fifelse(blank(gene), "no_unique_historical_A10_gene_mapping", "missing_variant_key")]\n}\nold <- copy(old[!blank(gene) & !is.na(variant)])\nif (!nrow(old)) stop("No identifiable historical C4 hypotheses remain")\nif (nrow(old) + nrow(old_unresolved) != nrow(old_all)) stop("Historical row accounting failed")\n'

def transform(text):
    edits = [('"predictions", "outdir"))', '"predictions", "outdir", "current_build", "legacy_build", "legacy_a10"))'), ('if (any(blank(old$gene)) || any(blank(old$variant))) stop("Historical C4 contains blank keys")', '# v1.1: explicit assembly declaration, key reconciliation, and audited historical repair.\nif (!identical(a$current_build, "GRCh38") || !identical(a$legacy_build, "GRCh38")) {\n  stop("This adapter supports explicitly declared GRCh38 inputs only; no liftover is performed")\n}\nif (!file.exists(a$legacy_a10)) stop("Missing historical A10: ", a$legacy_a10)\ninput_paths <- c(input_paths, legacy_a10 = a$legacy_a10)\ninput_hashes <- c(input_hashes, legacy_a10 = sha(a$legacy_a10))\nlegacy_a10 <- read_tab(a$legacy_a10)\nneed(legacy_a10, c("gene_symbol", "best_candidate_id"), "Historical A10")\ncanonical_id <- function(values) {\n  vapply(as.character(values), function(z) {\n    if (blank(z)) return(NA_character_)\n    z <- trimws(z)\n    if (grepl("^(GRCh[0-9]+|hg[0-9]+):", z, ignore.case = TRUE)) {\n      prefix <- sub(":.*$", "", z)\n      if (toupper(prefix) != "GRCH38") stop("Unexpected assembly prefix: ", prefix)\n      z <- sub("^[^:]+:", "", z)\n    }\n    fields <- strsplit(z, ":", fixed = TRUE)[[1]]\n    if (length(fields) != 4L || any(!nzchar(fields)) ||\n        !grepl("^[1-9][0-9]*$", fields[2])) stop("Unsupported coordinate-style candidate ID: ", z)\n    fields[1] <- sub("^chr", "", fields[1], ignore.case = TRUE)\n    if (fields[1] %in% c("x", "y", "mt", "m")) fields[1] <- toupper(fields[1])\n    if (fields[1] == "M") fields[1] <- "MT"\n    fields[3:4] <- toupper(fields[3:4])\n    paste(fields, collapse = ":")\n  }, character(1), USE.NAMES = FALSE)\n}\nset(x, j = "best_candidate_id_original", value = x$best_candidate_id)\nset(a2, j = "candidate_id_original", value = a2$candidate_id)\nset(f, j = "candidate_id_original", value = f$candidate_id)\nset(s, j = "candidate_id_original", value = as.character(s$candidate_id))\nset(x, j = "best_candidate_id", value = canonical_id(x$best_candidate_id))\nset(a2, j = "candidate_id", value = canonical_id(a2$candidate_id))\nset(f, j = "candidate_id", value = canonical_id(f$candidate_id))\nset(s, j = "candidate_id", value = canonical_id(s$candidate_id))\nfor (ids in list(x$best_candidate_id, a2$candidate_id, f$candidate_id, s$candidate_id)) {\n  if (anyNA(ids) || anyDuplicated(ids)) stop("Missing or colliding current IDs after format reconciliation")\n}\nold[, historical_source_row := .I]\nset(old, j = "original_gene", value = old$gene)\nset(old, j = "original_variant", value = old$variant)\nset(old, j = "variant", value = canonical_id(old$variant))\nset(old, j = "gene", value = trimws(old$gene))\nold[, key_repair_status := fifelse(blank(gene), "unresolved_missing_gene", "original_gene_present")]\nlookup <- unique(data.table(\n  variant = canonical_id(legacy_a10$best_candidate_id),\n  recovered_gene = trimws(legacy_a10$gene_symbol)\n))\nlookup <- lookup[!is.na(variant) & !blank(recovered_gene)]\nlookup <- lookup[, .(n_gene_mappings = uniqueN(recovered_gene), recovered_gene = recovered_gene[1L]), by = variant]\nli <- match(old$variant, lookup$variant)\nrepair <- which(blank(old$gene) & !is.na(li) & lookup$n_gene_mappings[li] == 1L)\nif (length(repair)) {\n  set(old, i = repair, j = "gene", value = lookup$recovered_gene[li[repair]])\n  set(old, i = repair, j = "key_repair_status", value = "gene_recovered_from_unique_historical_A10_allele_match")\n}\nold_all <- copy(old)\nold_unresolved <- copy(old[blank(gene) | is.na(variant)])\nif (nrow(old_unresolved)) {\n  old_unresolved[, unresolved_reason := fifelse(blank(gene), "no_unique_historical_A10_gene_mapping", "missing_variant_key")]\n}\nold <- copy(old[!blank(gene) & !is.na(variant)])\nif (!nrow(old)) stop("No identifiable historical C4 hypotheses remain")\nif (nrow(old) + nrow(old_unresolved) != nrow(old_all)) stop("Historical row accounting failed")'), ('set(reg, j = "a10_best_IMPACT", value = x$best_IMPACT[xi])', 'set(reg, j = "a10_best_IMPACT", value = x$best_IMPACT[xi])\nset(reg, j = "a10_variant_original", value = x$best_candidate_id_original[xi])'), ('old_keep <- copy(old)', 'old_keep <- copy(old_all)'), ('historical_C4 = "historical_C4_preserved.tsv")', 'historical_C4 = "historical_C4_preserved.tsv", unresolved = "historical_unresolved_rows.tsv")'), ('tables <- list(reg, links, primary, fh, sc, explore, old_keep)', 'tables <- list(reg, links, primary, fh, sc, explore, old_keep, old_unresolved)'), ('"Candidate registry = A10 UNION historical C4, keyed by gene and representative variant.",', '"Candidate registry = A10 UNION identifiable historical C4; unresolved historical rows retained separately.",\n  "GRCh38 explicitly declared for both sources. Format reconciliation only; no liftover, reference validation, or indel realignment.",\n  "Original allele identifiers are preserved. Historical missing genes are recovered only from unique historical A10 allele matches.",'), ('version = "A10_C4_union_Stan_v1"', 'version = "A10_C4_union_Stan_v1_1", current_build = a$current_build, legacy_build = a$legacy_build, historical_rows_total = nrow(old_all), historical_rows_gene_repaired = length(repair), historical_rows_unresolved = nrow(old_unresolved), historical_unresolved_unique_variants = uniqueN(old_unresolved$variant)'), ('cat("Outputs:", a$outdir, "\\n")', 'cat("Historical rows recovered:", length(repair), " | unresolved:", nrow(old_unresolved), "\\n")\ncat("Outputs:", a$outdir, "\\n")')]
    for old, new in edits:
        count = text.count(old)
        if count != 1:
            raise RuntimeError(f"Expected exactly one patch anchor, found {count}: {old[:100]!r}")
        text = text.replace(old, new, 1)
    return text

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", required=True)
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    src, dst = Path(a.source), Path(a.out)
    if dst.exists():
        raise SystemExit(f"Refusing to overwrite: {dst}")
    original = src.read_bytes()
    revised = transform(original.decode())
    with dst.open("x", encoding="utf-8") as f:
        f.write(revised)
    if src.read_bytes() != original:
        raise SystemExit("Source file changed unexpectedly")
    print(f"Created: {dst}")
    print(f"Source unchanged; new script SHA256: {hashlib.sha256(dst.read_bytes()).hexdigest()}")

if __name__ == "__main__":
    main()
